"""
桌面宠物 - 主入口
全局快捷键 CTRL+CTRL 唤醒/隐藏宠物
"""
import sys
import os

from PyQt5.QtWidgets import QApplication, QSystemTrayIcon, QMenu, QAction
from PyQt5.QtGui import QIcon
from PyQt5.QtCore import Qt
from PyQt5.QtGui import QPixmap

from pet_window import PetWindow
from hotkey_manager import HotkeyManager

import base64


# 解决 Windows 任务栏图标问题
try:
    from ctypes import windll
    APP_ID = "zhuochong.desktop.pet.v1"
    windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_ID)
except Exception:
    pass

DOG_PNG = ""


def convert_png():
    screen = QApplication.primaryScreen()
    ratio = screen.devicePixelRatio()

    # 从 Base64 字符串生成 QPixmap 对象
    pixmap = QPixmap()
    #pixmap.loadFromData(base64.b64decode(IMAGE_BASE64))
    pixmap.loadFromData(base64.b64decode(DOG_PNG))

    if not pixmap.isNull():
        small_pixmap = pixmap.scaled(
            int(100 * ratio), int(100 * ratio), # self.get_scaled_font_size(80), self.get_scaled_font_size(80),
            #80, 80,
            Qt.KeepAspectRatio, Qt.SmoothTransformation
        )
        small_pixmap.setDevicePixelRatio(ratio)
        return small_pixmap

def main():
    app = QApplication(sys.argv)
    app.setQuitOnLastWindowClosed(False)

    # ── 宠物窗口（默认不显示）───────────────────────────────
    pet = PetWindow()

    # ── 系统托盘 ────────────────────────────────────────────
    tray = QSystemTrayIcon()
    #icon_path = os.path.join(os.path.dirname(__file__), "resources", "icon.png")
    #if os.path.exists(icon_path):

    icon = convert_png()
    if icon:
        tray.setIcon(QIcon(icon))
    else:
        tray.setIcon(app.style().standardIcon(app.style().StandardPixmap.SP_ComputerIcon))

    tray_menu = QMenu()
    show_action = QAction("显示宠物", tray_menu)
    show_action.triggered.connect(lambda: pet.toggle_visibility() if not pet.isVisible() else None)
    tray_menu.addAction(show_action)

    # 风格切换子菜单
    style_menu = QMenu("切换风格", tray_menu)
    white_action = QAction("白色小狗", style_menu)
    white_action.triggered.connect(lambda: pet._switch_style("white"))
    style_menu.addAction(white_action)
    yellow_action = QAction("黄色小狗", style_menu)
    yellow_action.triggered.connect(lambda: pet._switch_style("yellow"))
    style_menu.addAction(yellow_action)
    tray_menu.addMenu(style_menu)

    tray_menu.addSeparator()

    quit_action = QAction("退出", tray_menu)
    quit_action.triggered.connect(app.quit)
    tray_menu.addAction(quit_action)

    tray.setContextMenu(tray_menu)
    tray.setToolTip("桌面宠物 - CTRL+CTRL 唤醒")
    tray.show()

    tray.activated.connect(lambda reason: pet.show() if reason == QSystemTrayIcon.DoubleClick else None)

    # ── 全局快捷键 ──────────────────────────────────────────
    hotkey = HotkeyManager(double_press_interval=0.5)
    hotkey.toggle_requested.connect(pet.toggle_visibility)
    hotkey.pin_requested.connect(pet.toggle_pin)
    hotkey.start()

    # ── 运行 ────────────────────────────────────────────────
    print("[桌面宠物] 已启动！")
    print("[桌面宠物] 按 CTRL+CTRL 唤醒/隐藏宠物")
    print("[桌面宠物] 按 SHIFT+SHIFT 钉住/解除钉住（宠物可见时）")
    print("[桌面宠物] 右键宠物 → 关闭 / 切换风格")
    print("[桌面宠物] 左键单击 → 互动动画")
    print("[桌面宠物] 鼠标悬停 → 摇摆动画")

    sys.exit(app.exec_())


if __name__ == "__main__":
    main()